(function(){
  function slug(text){
    text=String(text==null?'':text).normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
    text=text.replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
    return {value:text};
  }
  var API={slug:slug};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__SlugifyForge__=API;
})();
